import {createClient} from 'npm:@supabase/supabase-js@2.112.4';
const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');
const db=createClient(Deno.env.get('SUPABASE_URL')!,keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false,autoRefreshToken:false}});
async function secret(){const {data,error}=await db.rpc('get_bot_secret',{secret_name:'internal_worker_secret'});if(error||!data)throw Error('secret');return String(data)}
const TARGET_URL='https://www.kleinanzeigen.de/nachrichten/s-anbieter-kontaktieren/3513898714/26488-22303-hamburg-barmbek-nord/203-Wohnung_mieten';
const UA='Mozilla/5.0 (Linux; Android 16; Pixel 9 Pro) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Mobile Safari/537.36';
function contexts(text:string,p:string,max=10){const out=[];const l=text.toLowerCase(),q=p.toLowerCase();let a=0;while(out.length<max){const i=l.indexOf(q,a);if(i<0)break;out.push(text.slice(Math.max(0,i-300),Math.min(text.length,i+500)).replace(/\s+/g,' '));a=i+q.length}return out}
Deno.serve(async req=>{try{if(req.headers.get('x-internal-secret')!==await secret())return new Response('no',{status:401});const manual=await fetch(TARGET_URL,{redirect:'manual',headers:{'user-agent':UA,accept:'text/html,application/xhtml+xml,*/*','accept-language':'de-DE,de;q=0.9'},signal:AbortSignal.timeout(15000)});const mt=await manual.text();const follow=await fetch(TARGET_URL,{redirect:'follow',headers:{'user-agent':UA,accept:'text/html,application/xhtml+xml,*/*','accept-language':'de-DE,de;q=0.9'},signal:AbortSignal.timeout(15000)});const text=await follow.text();const ps=['login','csrf','form','action=','nachricht','profilname','telefonnummer','anfrage-qualität','anfrage','extended','kare-2687','anbieter-kontaktieren','messagebox','conversation','contact'];const hits:any={};for(const p of ps){const c=contexts(text,p);if(c.length)hits[p]=c}const forms=[...text.matchAll(/<form\b[^>]*>/gi)].map(m=>m[0]);const scripts=[...text.matchAll(/<script\b[^>]*\bsrc=["']([^"']+)["'][^>]*>/gi)].map(m=>{try{return new URL(m[1],follow.url).href}catch{return m[1]}});return Response.json({manual:{status:manual.status,location:manual.headers.get('location'),bytes:mt.length,setCookie:!!manual.headers.get('set-cookie')},follow:{status:follow.status,url:follow.url,bytes:text.length,setCookie:!!follow.headers.get('set-cookie')},forms,patterns:Object.keys(hits),hits,scripts});}catch(e){return Response.json({error:String((e as any)?.message||e)},{status:500})}});

import { fetchListingPage } from "./fetch-page.ts";
import { createClient } from "npm:@supabase/supabase-js@2.112.4";
const SUPABASE_URL=Deno.env.get('SUPABASE_URL')!;
const KEY=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}').default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
const db=createClient(SUPABASE_URL,KEY,{auth:{persistSession:false,autoRefreshToken:false}});
async function secret(){const{data,error}=await db.rpc('get_bot_secret',{secret_name:'internal_worker_secret'});if(error||!data)throw new Error('internal secret unavailable');return String(data)}
Deno.serve(async req=>{try{if(req.method!=='POST')return new Response('method not allowed',{status:405});if((req.headers.get('x-internal-secret')||'')!==await secret())return new Response('unauthorized',{status:401});const body=await req.json().catch(()=>({}));return fetchListingPage(String(body?.url||''),req.signal)}catch(e){return new Response(e instanceof Error?e.message:String(e),{status:502,headers:{'cache-control':'no-store'}})}});

const UA='Mozilla/5.0 (compatible; TraumwohnungHamburgBot/13.0; +https://traumwohnunghamburg.de)';

export async function fetchListingPage(raw: string, signal?: AbortSignal): Promise<Response> {
  try {
    const url=new URL(raw);
    if(url.protocol!=='https:' || url.hostname!=='www.kleinanzeigen.de' || url.port || url.username || url.password || !/^\/s-(?:wohnung-mieten|haus-mieten|auf-zeit-wg)\//.test(url.pathname))
      return new Response('invalid target',{status:400});
    const response=await fetch(url.href,{
      redirect:'follow',
      headers:{'user-agent':UA,accept:'text/html,application/xhtml+xml,*/*','accept-language':'de-DE,de;q=0.9','cache-control':'no-cache'},
      signal:AbortSignal.any([AbortSignal.timeout(12000),...(signal?[signal]:[])]),
    });
    const html=await response.text();
    signal?.throwIfAborted();
    return new Response(html,{status:200,headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-upstream-status':String(response.status),'x-upstream-url':response.url}});
  } catch(error) {
    return new Response(error instanceof Error?error.message:String(error),{status:502,headers:{'cache-control':'no-store'}});
  }
}
